import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const css=read('studio-sidebar-modern.css');
const base=read('studio-vision.css'),index=read('index.php'),sw=read('sw.js'),js=read('script.js');
const start=css.indexOf('/* Android touchscreen navigation — horizontal');
assert.ok(start>0,'Last-loaded stylesheet includes touch navigation patch');
const patch=css.slice(start);
assert.match(base,/flex-direction:column!important/,'Tablet layout originally stacked icons');
assert.match(patch,/@media \(min-width:769px\) and \(max-width:1199px\)/);
assert.match(patch,/@media \(min-width:769px\) and \(pointer:coarse\)/);
assert.match(patch,/@media \(max-width:768px\)/);
assert.match(patch,/\.showcase-nav-btn \{\s*display:flex!important;flex-direction:row!important/);
assert.match(patch,/\.showcase-nav-btn > span \{\s*display:block!important/);
assert.match(patch,/min-height:54px!important/);
assert.match(patch,/min-height:56px!important/);
assert.match(patch,/touch-action:manipulation/);
assert.match(patch,/grid-template-columns:clamp\(185px,20vw,222px\)/);
assert.match(patch,/\.showcase-nav-btn:active/);
assert.match(patch,/prefers-reduced-motion:reduce/);
assert.match(index,/studio-sidebar-modern\.css\?v=12/);
assert.match(sw,/studio-sidebar-modern\.css\?v=12/);
assert.match(index,/script\.js\?v=2393/);
assert.match(sw,/dagstudio-player-shell-v2411/);
assert.match(js,/WEB_BUILD_LABEL = '2393'/);
console.log('ANDROID_LANDSCAPE_AND_MOBILE_SIDEBAR_HORIZONTAL_TOUCH_MENU_OK');
